{"file_path":"src/parse.js","content":"import { CliError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph from the raw text read from standard input.
 * Returns { tasks: Map<name, cost>, adjacency: Map<name, string[]> }.
 * Throws CliError for any malformed input.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const adjacency = new Map()
  const usedNames = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
      if (!adjacency.has(name)) adjacency.set(name, [])
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      const deps = words.slice(2)
      usedNames.push(name)
      if (!adjacency.has(name)) adjacency.set(name, [])
      const list = adjacency.get(name)
      for (const dep of deps) {
        usedNames.push(dep)
        if (!list.includes(dep)) list.push(dep)
      }
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  for (const name of usedNames) {
    if (!tasks.has(name)) {
      throw new CliError(`unknown task ${name}`)
    }
  }

  return { tasks, adjacency }
}
"}

