{"file_path":"src/schedule.js","content":"import { CycleError } from './errors.js'
import { findCycle } from './cycle.js'

/**
 * Computes start, finish and depth for every task given its dependency
 * graph. Throws CycleError when the graph is not a DAG.
 */
export function computeSchedule(names, tasks, adjacency) {
  const cycle = findCycle(names, adjacency)
  if (cycle) throw new CycleError(cycle)

  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    const deps = adjacency.get(name) || []
    let start = 0
    let depth = 0
    for (const dep of deps) {
      const r = compute(dep)
      if (r.finish > start) start = r.finish
      if (r.depth + 1 > depth) depth = r.depth + 1
    }
    const finish = start + tasks.get(name)
    const result = { start, finish, depth }
    memo.set(name, result)
    return result
  }

  const results = new Map()
  let total = 0
  for (const name of names) {
    const r = compute(name)
    results.set(name, r)
    if (r.finish > total) total = r.finish
  }

  return { results, total }
}
"}

