{"file_path":"src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers, greedily
 * starting the ready task with the greatest priority whenever a worker
 * is free. Priority is the cost of the longest chain of dependents that
 * begins at a task, counting its own cost and continuing down to a task
 * that nothing depends on.
 */
function computePriorities(names, tasks, adjacency) {
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const [name, deps] of adjacency) {
    for (const dep of deps) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(name)
    }
  }

  const memo = new Map()
  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    let maxDown = 0
    for (const dependent of dependents.get(name) || []) {
      const p = compute(dependent)
      if (p > maxDown) maxDown = p
    }
    const result = tasks.get(name) + maxDown
    memo.set(name, result)
    return result
  }

  const priorities = new Map()
  for (const name of names) priorities.set(name, compute(name))
  return priorities
}

export function computePack(names, tasks, adjacency, workerCount) {
  const priorities = computePriorities(names, tasks, adjacency)
  const finishOf = new Map()
  const scheduled = new Set()
  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, log: [] }))
  let currentInstant = 0
  const total = names.length

  while (scheduled.size < total) {
    for (;;) {
      let freeIdx = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].busyUntil <= currentInstant) {
          freeIdx = i
          break
        }
      }
      if (freeIdx === -1) break

      let best = null
      for (const name of names) {
        if (scheduled.has(name)) continue
        const deps = adjacency.get(name) || []
        let ready = true
        for (const dep of deps) {
          if (!finishOf.has(dep) || finishOf.get(dep) > currentInstant) {
            ready = false
            break
          }
        }
        if (!ready) continue
        const p = priorities.get(name)
        if (!best || p > best.p || (p === best.p && name < best.name)) {
          best = { name, p }
        }
      }
      if (!best) break

      const start = currentInstant
      const finish = start + tasks.get(best.name)
      finishOf.set(best.name, finish)
      scheduled.add(best.name)
      workers[freeIdx].busyUntil = finish
      workers[freeIdx].log.push({ name: best.name, start, finish })
    }

    if (scheduled.size >= total) break

    let next = Infinity
    for (const w of workers) {
      if (w.busyUntil > currentInstant && w.busyUntil < next) next = w.busyUntil
    }
    if (next === Infinity) break
    currentInstant = next
  }

  let makespan = 0
  for (const f of finishOf.values()) if (f > makespan) makespan = f

  return { workers, makespan }
}
"}

