{"file_path":"src/cycle.js","content":"/**
 * Depth-first cycle detection. Starts from each task in ascending name
 * order and walks each task's dependencies in ascending name order.
 * Returns the first cycle found, as an array of names running from the
 * re-entered task through the search stack back to itself, or null when
 * the graph is acyclic.
 */
export function findCycle(names, adjacency) {
  const state = new Map()
  const stack = []

  function visit(node) {
    state.set(node, 1)
    stack.push(node)
    const deps = [...(adjacency.get(node) || [])].sort()
    for (const dep of deps) {
      const st = state.get(dep) || 0
      if (st === 1) {
        const idx = stack.indexOf(dep)
        const cyclePath = stack.slice(idx)
        cyclePath.push(dep)
        return cyclePath
      } else if (st === 0) {
        const found = visit(dep)
        if (found) return found
      }
    }
    stack.pop()
    state.set(node, 2)
    return null
  }

  for (const name of names) {
    if ((state.get(name) || 0) === 0) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}
"}

