{"file_path":"src/schedule.js","content":"import { CycleError } from './errors.js'
import { findCycle } from './cycle.js'

/**
 * Computes start, finish and depth for every task given its dependency
 * graph. Throws CycleError when the graph is not a DAG.
 */
export function computeSchedule(names, tasks, adjacency) {
  const cycle = findCycle(names, adjacency)
  if (cycle) throw new CycleError(cycle)

  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    const deps = adjacency.get(name) || []
    let start = 0
    let depth = 0
    for (const dep of deps) {
      const r = compute(dep)
      if (r.finish > start) start = r.finish
      if (r.depth + 1 > depth) depth = r.depth + 1
    }
    const finish = start + tasks.get(name)
    const result = { start, finish, depth }
    memo.set(name, result)
    return result
  }

  const results = new Map()
  let total = 0
  for (const name of names) {
    const r = compute(name)
    results.set(name, r)
    if (r.finish > total) total = r.finish
  }

  return { results, total }
}
"}

{"file_path":"src/pack.js","content":"/**
 * Simulates the build graph on a fixed number of workers, greedily
 * starting the ready task with the greatest priority whenever a worker
 * is free. Priority is the cost of the longest chain of dependents that
 * begins at a task, counting its own cost and continuing down to a task
 * that nothing depends on.
 */
function computePriorities(names, tasks, adjacency) {
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const [name, deps] of adjacency) {
    for (const dep of deps) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(name)
    }
  }

  const memo = new Map()
  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    let maxDown = 0
    for (const dependent of dependents.get(name) || []) {
      const p = compute(dependent)
      if (p > maxDown) maxDown = p
    }
    const result = tasks.get(name) + maxDown
    memo.set(name, result)
    return result
  }

  const priorities = new Map()
  for (const name of names) priorities.set(name, compute(name))
  return priorities
}

export function computePack(names, tasks, adjacency, workerCount) {
  const priorities = computePriorities(names, tasks, adjacency)
  const finishOf = new Map()
  const scheduled = new Set()
  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, log: [] }))
  let currentInstant = 0
  const total = names.length

  while (scheduled.size < total) {
    for (;;) {
      let freeIdx = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].busyUntil <= currentInstant) {
          freeIdx = i
          break
        }
      }
      if (freeIdx === -1) break

      let best = null
      for (const name of names) {
        if (scheduled.has(name)) continue
        const deps = adjacency.get(name) || []
        let ready = true
        for (const dep of deps) {
          if (!finishOf.has(dep) || finishOf.get(dep) > currentInstant) {
            ready = false
            break
          }
        }
        if (!ready) continue
        const p = priorities.get(name)
        if (!best || p > best.p || (p === best.p && name < best.name)) {
          best = { name, p }
        }
      }
      if (!best) break

      const start = currentInstant
      const finish = start + tasks.get(best.name)
      finishOf.set(best.name, finish)
      scheduled.add(best.name)
      workers[freeIdx].busyUntil = finish
      workers[freeIdx].log.push({ name: best.name, start, finish })
    }

    if (scheduled.size >= total) break

    let next = Infinity
    for (const w of workers) {
      if (w.busyUntil > currentInstant && w.busyUntil < next) next = w.busyUntil
    }
    if (next === Infinity) break
    currentInstant = next
  }

  let makespan = 0
  for (const f of finishOf.values()) if (f > makespan) makespan = f

  return { workers, makespan }
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { CliError, CycleError } from './errors.js'
import { parseGraph } from './parse.js'
import { computeSchedule } from './schedule.js'
import { computePack } from './pack.js'

const WORKERS_RE = /^[1-9][0-9]*$/

function parseArgs(argv) {
  if (argv.length === 1 && argv[0] === 'waves') return { mode: 'waves' }
  if (argv.length === 1 && argv[0] === 'explain') return { mode: 'explain' }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('workers must be a positive integer')
    }
    return { mode: 'pack', workerCount: Number(argv[1]) }
  }
  throw new CliError('usage: cli.js waves|explain|pack <workers>')
}

function formatWaves(names, results, total) {
  const byDepth = new Map()
  for (const name of names) {
    const d = results.get(name).depth
    if (!byDepth.has(d)) byDepth.set(d, [])
    byDepth.get(d).push(name)
  }
  const maxDepth = byDepth.size ? Math.max(...byDepth.keys()) : -1
  let out = ''
  for (let d = 0; d <= maxDepth; d++) {
    out += `wave ${d}: ${byDepth.get(d).join(' ')}\n`
  }
  out += `total ${total}\n`
  return out
}

function formatExplain(names, results, total) {
  let out = ''
  for (const name of names) {
    const r = results.get(name)
    out += `${name} start=${r.start} finish=${r.finish} depth=${r.depth}\n`
  }
  out += `total ${total}\n`
  return out
}

function formatPack(workers, makespan) {
  let out = ''
  workers.forEach((w, i) => {
    const parts = w.log.map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
    out += `worker ${i}:${parts}\n`
  })
  out += `makespan ${makespan}\n`
  return out
}

function main() {
  const { mode, workerCount } = parseArgs(process.argv.slice(2))

  const input = readFileSync(0, 'utf8')
  const { tasks, adjacency } = parseGraph(input)
  const names = [...tasks.keys()].sort()

  if (mode === 'pack') {
    const { workers, makespan } = computePack(names, tasks, adjacency, workerCount)
    return formatPack(workers, makespan)
  }

  const { results, total } = computeSchedule(names, tasks, adjacency)
  if (mode === 'waves') return formatWaves(names, results, total)
  return formatExplain(names, results, total)
}

try {
  const out = main()
  process.stdout.write(out, () => process.exit(0))
} catch (err) {
  if (err instanceof CycleError) {
    process.stderr.write(`error: ${err.message}\n`, () => process.exit(3))
  } else if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`, () => process.exit(2))
  } else {
    throw err
  }
}
"}

