import { Heap } from './heap.js'

/**
 * Priority is the cost of the longest chain of dependents that begins at
 * a task, counting its own cost and continuing down to a task that
 * nothing depends on.
 */
function computePriorities(names, tasks, adjacency, finishOrder) {
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const [name, deps] of adjacency) {
    for (const dep of deps) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(name)
    }
  }

  const priorities = new Map()
  // Dependents must be resolved before the tasks they depend on, which is
  // the reverse of the dependency-first finish order.
  for (let i = finishOrder.length - 1; i >= 0; i--) {
    const name = finishOrder[i]
    let maxDown = 0
    for (const dependent of dependents.get(name) || []) {
      const p = priorities.get(dependent)
      if (p > maxDown) maxDown = p
    }
    priorities.set(name, tasks.get(name) + maxDown)
  }
  return { priorities, dependents }
}

/**
 * Simulates the build graph on a fixed number of workers, greedily
 * starting the ready task with the greatest priority whenever a worker
 * is free. Throws CycleError when the graph is not a DAG.
 */
export function computePack(names, tasks, adjacency, workerCount) {
  const { cycle, finishOrder } = traverse(names, adjacency)
  if (cycle) throw new CycleError(cycle)

  const { priorities, dependents } = computePriorities(names, tasks, adjacency, finishOrder)

  const indegree = new Map()
  for (const name of names) indegree.set(name, (adjacency.get(name) || []).length)

  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, log: [] }))

  const freeWorkers = new Heap((a, b) => a - b)
  for (let i = 0; i < workerCount; i++) freeWorkers.push(i)

  const ready = new Heap((a, b) => {
    const pa = priorities.get(a)
    const pb = priorities.get(b)
    if (pa !== pb) return pb - pa
    return a < b ? -1 : a > b ? 1 : 0
  })
  for (const name of names) if (indegree.get(name) === 0) ready.push(name)

  const events = new Heap((a, b) => a.finish - b.finish)

  let currentInstant = 0
  let scheduledCount = 0
  const total = names.length
  const finishOf = new Map()

  while (scheduledCount < total) {
    let progressed = true
    while (progressed) {
      progressed = false

      while (events.size() && events.peek().finish <= currentInstant) {
        const ev = events.pop()
        freeWorkers.push(ev.workerIdx)
        for (const dep of dependents.get(ev.name) || []) {
          const d = indegree.get(dep) - 1
          indegree.set(dep, d)
          if (d === 0) ready.push(dep)
        }
        progressed = true
      }

      while (freeWorkers.size() && ready.size()) {
        const w = freeWorkers.pop()
        const t = ready.pop()
        const start = currentInstant
        const finish = start + tasks.get(t)
        finishOf.set(t, finish)
        workers[w].busyUntil = finish
        workers[w].log.push({ name: t, start, finish })
        events.push({ finish, name: t, workerIdx: w })
        scheduledCount++
        progressed = true
      }
    }

    if (scheduledCount >= total) break
    if (events.size() === 0) break
    currentInstant = events.peek().finish
  }

  let makespan = 0
  for (const f of finishOf.values()) if (f > makespan) makespan = f

  return { workers, makespan }
}
